{$ param image_url label="Image URL" default="https://picsum.photos/800/400" description="Module image." type="fileurl" $}
{$ param image_alt label="Image Alt" default="" description="Accessibility description." $}
{$ param title label="Module Title" default="Training Module" description="Card heading." $}
{$ param href label="Module URL" default="#" description="Where the title and CTA link." $}
{$ param cta_label label="CTA Label" default="Learn More" description="Button text." $}

<div class="ss-project-card mb-4">
  <a href="{$= href $}" class="w-full flex flex-col sm:flex-row bg-white shadow-md mx-auto mb-4 border border-primary-light rounded-md overflow-hidden no-underline">
    <img src="{$= image_url $}" alt="{$= image_alt $}" class="w-full sm:w-[300px] self-start sm:max-w-[33%]" />
    <div class="flex flex-col p-4 justify-center gap-4 w-full">
      <div>
        <h3 class="text-lg mb-2! text-primary-dark">{$= title $}</h3>
        {$ slot description $}
          <p class="text-sm mb-4! text-neutral-dark">Description of the training module.</p>
        {$ /slot $}
        <span class="btn btn-primary mt-4">{$= cta_label $}</span>
      </div>
    </div>
  </a>
</div>
